const m=$('Build Entity Map').first().json; const fbMap=m.fbMap||{}; const entity_ids=Object.keys(fbMap);
const snapshots=entity_ids.map(eid=>{ const ins=fbMap[eid].insights; const spend=ins?parseFloat(ins.spend||0):0; const entity_type=String(eid).startsWith('act_')?'account':'campaign'; return {entity_id:eid,entity_type,spend}; });
return [{json:{snapshots,entity_ids}}];

const burstData_1h=$input.item.json||{};
const burstData=$('Check Burst').first().json||{};
const garItems=$('Get Active Rules').all(); let rules;
if(garItems.length===1){ const j=garItems[0].json; rules=Array.isArray(j)?j:Array.isArray(j.data)?j.data:Array.isArray(j.rules)?j.rules:[j]; }
else { rules=garItems.map(i=>i.json); }
return rules.map(rule=>({json:{...rule,burstData,burstData_1h}}));

const { burstData: burstDataRaw, burstData_1h: burstDataRaw1h, ...rule } = $input.item.json;
const entities = rule.entities || [];
const token = rule.token || (entities[0] && entities[0].token) || null;
const fbMap = $('Build Entity Map').first().json.fbMap || {};
const isAccountScope = rule.scope === 'account' && entities.every(e => String(e.entityId).startsWith('act_'));
const burstData = burstDataRaw || {};
const burstData_1h = burstDataRaw1h || {};
const n = entities.length;

const nowET = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const time_of_day_et = nowET.getHours() * 60 + nowET.getMinutes();
const day_of_week = nowET.getDay() === 0 ? 7 : nowET.getDay();

function parseInsights(d, rt, statusBody) {
  if (!d) return null;

  const spend = parseFloat(d.spend || 0);
  const fbConv = parseFloat(d.actions?.find(a => a.action_type === 'purchase')?.value || 0);
  const conversions = rt ? (rt.conversions || 0) : fbConv;
  const cpa = conversions > 0 ? spend / conversions : 0;
  const roas = parseFloat(d.purchase_roas?.[0]?.value || 0);
  const purchaseValue = parseFloat(d.action_values?.find(a => a.action_type === 'purchase')?.value || 0);
  // RT cost lags FB intraday spend — use the larger of the two as today's cost
  // basis so a kill rule never sees an optimistic ROI while FB spend runs ahead.
  const rtRevenue = rt ? (rt.revenue || 0) : 0;
  const rtCost = rt ? Math.max(0, rtRevenue - (rt.profit || 0)) : 0;
  const effCost = Math.max(rtCost, spend);
  const roi = rt ? (effCost > 0 ? (rtRevenue - effCost) / effCost : 0) : (spend > 0 && purchaseValue > 0 ? (purchaseValue - spend) / spend : null);
  const roi_rt = rt ? (rt.roi ?? null) : null;
  const revenue = rt ? rtRevenue : purchaseValue;
  const profit = rt ? (rtRevenue - effCost) : (purchaseValue - spend);

  const ctr = parseFloat(d.ctr || 0);
  const cpc = parseFloat(d.cpc || 0);
  const frequency = parseFloat(d.frequency || 0);
  const link_clicks = parseFloat(d.inline_link_clicks || 0);
  const lp_views = parseFloat(d.actions?.find(a => a.action_type === 'landing_page_view')?.value || 0);
  const initiate_checkout = parseFloat(d.actions?.find(a => a.action_type === 'initiate_checkout')?.value || 0);
  const outbound_clicks_ctr = parseFloat(d.outbound_clicks_ctr?.[0]?.value || 0);
  const lp_conv_rate = link_clicks > 0 ? (lp_views / link_clicks) * 100 : 0;

  const dailyBudgetCents = statusBody ? parseInt(statusBody.daily_budget || 0) : 0;
  const remainingCents = statusBody ? parseInt(statusBody.budget_remaining || 0) : 0;
  const budget_pct_used = dailyBudgetCents > 0 ? ((dailyBudgetCents - remainingCents) / dailyBudgetCents) * 100 : 0;
  const budget_remaining_pct = 100 - budget_pct_used;

  return {
    spend_today: spend, conversions, cpa, roas, roi, roi_rt, revenue, profit,
    ctr, cpc, frequency, link_clicks, lp_views, initiate_checkout,
    outbound_clicks_ctr, lp_conv_rate,
    budget_pct_used, budget_remaining_pct,
    time_of_day_et, day_of_week,
  };
}

const conditions = rule.conditions || [];
const combinator = rule.combinator || 'AND';
const triggered = [];

for (let i = 0; i < n; i++) {
  const entity = entities[i];
  const entityId = entity.entityId;
  const entityToken = entity.token || token;

  const fb = fbMap[entityId] || { status: null, insights: null };
  const statusBody = fb.status;
  let entityName = entityId;
  if (statusBody) {
    entityName = statusBody.name || entity.entityName || entityId;
    if (statusBody.effective_status === 'PAUSED' && rule.action !== 'enable') continue;
  }

  const todayInsights = parseInsights(fb.insights, entity.rt, statusBody);
  const insights3d = entity.insights_3d || null;
  const insights7d = entity.insights_7d || null;
  if (!todayInsights) continue;

  const burst = burstData[entityId] || {};
  const burstMetrics = { burst_multiplier: burst.burst_multiplier || 0, spend_30m: burst.spend_recent || 0, avg_30m: burst.avg_period || 0 };
  const burst1h = burstData_1h[entityId] || {};
  const burstMetrics1h = { burst_multiplier: burst1h.burst_multiplier || 0, spend_1h: burst1h.spend_recent || 0, avg_1h: burst1h.avg_period || 0 };

  const evaluate = (c) => {
    if (c.lookback === 'last_30m') {
      const val = burstMetrics[c.metric];
      if (val == null) return false;
      switch (c.operator) { case 'gt': return val > c.value; case 'lt': return val < c.value; case 'gte': return val >= c.value; case 'lte': return val <= c.value; case 'eq': return val === c.value; default: return false; }
    }
    if (c.lookback === 'last_1h') {
      const val = burstMetrics1h[c.metric];
      if (val == null) return false;
      switch (c.operator) { case 'gt': return val > c.value; case 'lt': return val < c.value; case 'gte': return val >= c.value; case 'lte': return val <= c.value; case 'eq': return val === c.value; default: return false; }
    }
    const src = c.lookback === 'last_7d' ? insights7d : c.lookback === 'last_3d' ? insights3d : todayInsights;
    let val;
    if (c.metric === 'spend') {
      val = c.lookback === 'today' ? src?.spend_today : src?.spend;
    } else {
      val = src?.[c.metric];
    }
    if (val == null) return false;
    switch (c.operator) { case 'gt': return val > c.value; case 'lt': return val < c.value; case 'gte': return val >= c.value; case 'lte': return val <= c.value; case 'eq': return val === c.value; default: return false; }
  };

  const allMet = combinator === 'OR' ? conditions.some(evaluate) : conditions.every(evaluate);
  if (allMet) {
    triggered.push({ json: { rule, entityId, entityName, metrics: { ...todayInsights, ...burstMetrics }, insights_3d: insights3d, insights_7d: insights7d, token: entityToken } });
  }
}

if (rule.scope === 'account' && conditions.length > 0) {
  const _acctSpend = entities.reduce((sum, e) => { const ins = (fbMap[e.entityId] || {}).insights; return sum + (ins ? parseFloat(ins.spend || 0) : 0); }, 0);
  const _acctMetrics = { spend: _acctSpend, spend_today: _acctSpend, account_spend_today: _acctSpend, account_spend: _acctSpend };
  const _evalAcct = (c) => { const val = c.metric === 'spend' ? _acctSpend : _acctMetrics[c.metric]; if (val == null) return false; switch (c.operator) { case 'gt': return val > c.value; case 'lt': return val < c.value; case 'gte': return val >= c.value; case 'lte': return val <= c.value; case 'eq': return val === c.value; default: return false; } };
  const _acctAllMet = combinator === 'OR' ? conditions.some(_evalAcct) : conditions.every(_evalAcct);
  const isAcct = isAccountScope;
  if (isAcct) {
    const totalSpend = entities.reduce((sum, e) => {
      const ins = (fbMap[e.entityId] || {}).insights;
      return sum + (ins ? parseFloat(ins.spend || 0) : 0);
    }, 0);
    const condition = conditions[0];
    if (_acctAllMet) {
      const campaignItems = [];
      for (const e of entities) {
        for (const cid of (e.campaignIds || [])) {
          campaignItems.push({ json: { rule, entityId: String(cid), entityName: `Campaign ${cid} (Acct ${e.entityId})`, metrics: { spend_today: totalSpend, account_spend_today: totalSpend }, token: e.token || token } });
        }
      }
      if (campaignItems.length > 0) return campaignItems;
      return [{ json: { noTrigger: true } }];
    }
    return [{ json: { noTrigger: true } }];
  }
  const totalSpend = entities.reduce((sum, e) => {
    const ins = (fbMap[e.entityId] || {}).insights;
    return sum + (ins ? parseFloat(ins.spend || 0) : 0);
  }, 0);
  const condition = conditions[0];
  if (_acctAllMet) {
    return entities.map((e) => {
      const fb = fbMap[e.entityId] || { status: null, insights: null };
      let entityName = e.entityId;
      if (fb.status) entityName = fb.status.name || e.entityId;
      const spend = fb.insights ? parseFloat(fb.insights.spend || 0) : 0;
      return { json: { rule, entityId: e.entityId, entityName, metrics: { spend_today: spend, account_spend_today: totalSpend }, token: e.token || token } };
    });
  }
  return [{ json: { noTrigger: true } }];
}

return triggered.length > 0 ? triggered : [{ json: { noTrigger: true } }];

const d = $input.item.json;
return [{ json: {
  rule_id: d.rule.id,
  entity_type: d.rule.scope,
  entity_id: d.entityId,
  entity_name: d.entityName || d.entityId,
  action_taken: 'would_have_' + d.rule.action + 'd',
  trigger_data_json: JSON.stringify(d.metrics),
  is_dry_run: 1,
  _restore: d
} }];

const d = $input.item.json;
const m = d.metrics || {};
const m3d = d.insights_3d || {};
const m7d = d.insights_7d || {};
const name = d.entityName || d.entityId || '';
const ruleName = (d.rule && d.rule.name) || '';
const ruleAction = (d.rule && d.rule.action) || 'action';
const time = new Date().toLocaleTimeString('en-US', {timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit'}) + ' ET';
const isBurst = ((d.rule && d.rule.conditions) || []).some(c => c.lookback === 'last_30m');
const actionLabel = String(ruleAction).toUpperCase().replace(/_/g, ' ');

function getSrc(lookback) {
  if (lookback === 'last_7d') return m7d;
  if (lookback === 'last_3d') return m3d;
  return m;
}

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const safeNum = (v, d2) => (typeof v === 'number' && isFinite(v)) ? v.toFixed(d2) : '0';

function fmtMetric(metric, val, lookback) {
  const lb = (lookback && lookback !== 'today') ? ' ·' + String(lookback).replace('last_', '') : '';
  if (val == null || !isFinite(val)) return '';
  if (metric === 'roi') return 'ROI' + lb + ': ' + (val * 100).toFixed(1) + '%';
  if (metric === 'cpa') return 'CPA' + lb + ': $' + val.toFixed(0);
  if (metric === 'conversions') return 'Conv' + lb + ': ' + Math.round(val);
  if (metric === 'ctr') return 'CTR' + lb + ': ' + val.toFixed(2) + '%';
  if (metric === 'cpc') return 'CPC' + lb + ': $' + val.toFixed(2);
  if (metric === 'frequency') return 'Freq' + lb + ': ' + val.toFixed(1);
  if (metric === 'link_clicks') return 'Clicks' + lb + ': ' + Math.round(val);
  if (metric === 'lp_views') return 'LPV' + lb + ': ' + Math.round(val);
  if (metric === 'spend' || metric === 'spend_today') return 'Spend' + lb + ': $' + val.toFixed(0);
  if (metric === 'revenue') return 'Rev' + lb + ': $' + val.toFixed(0);
  return esc(metric) + lb + ': ' + esc(val);
}

let text;
try {
  if (isBurst) {
    const burst = d.burstMetrics || {};
    const pct = ((burst.burst_multiplier || 0) * 100).toFixed(0);
    text = '🧪 <b>[DRY RUN]</b> 💥 ' + esc(ruleName) + '\n<code>' + esc(name) + '</code>  |  would PAUSE\nLast 30 min: $' + safeNum(burst.spend_30m, 0) + ' spent (normal: $' + safeNum(burst.avg_30m, 0) + ') — ' + pct + '%\n' + time;
  } else {
    const parts = [];
    if (m.spend_today != null && isFinite(m.spend_today)) parts.push('Spend today: $' + m.spend_today.toFixed(0));
    const shown = new Set(['spend']);
    for (const c of ((d.rule && d.rule.conditions) || [])) {
      if (!c || shown.has(c.metric)) continue;
      shown.add(c.metric);
      const src = getSrc(c.lookback);
      const val = src ? src[c.metric] : null;
      if (val == null) continue;
      const line = fmtMetric(c.metric, val, c.lookback);
      if (line) parts.push(line);
    }
    // Always-on context so ROI can be sanity-checked from the message alone
    for (const extra of ['revenue', 'conversions', 'cpa']) {
      if (shown.has(extra)) continue;
      const val = m[extra];
      if (val == null || !isFinite(val)) continue;
      shown.add(extra);
      const line = fmtMetric(extra, val, 'today');
      if (line) parts.push(line);
    }
    // RT-basis ROI when it diverges >2pts from effective-cost ROI (RT cost-lag indicator)
    if (m.roi_rt != null && isFinite(m.roi_rt) && m.roi != null && isFinite(m.roi) && Math.abs(m.roi_rt - m.roi) > 0.02) {
      parts.push('ROI·rt: ' + (m.roi_rt * 100).toFixed(1) + '%');
    }
    const metricsLine = parts.join('  |  ');
    text = '🧪 <b>[DRY RUN]</b> ' + esc(ruleName) + '\n<code>' + esc(name) + '</code>  |  would ' + esc(actionLabel) + (metricsLine ? '\n' + metricsLine : '') + '\n' + time;
  }
} catch (e) {
  text = '🧪 [DRY RUN] ' + String(ruleName) + ' — ' + String(name) + ' (alert build error: ' + e.message + ')';
}

const ruleId = (d.rule && d.rule.id) || '';
const entityId = d.entityId || '';
const btns = [];
if (ruleAction === 'pause') btns.push({ text: '✅ Approve & Pause', callback_data: 'approve_pause:' + ruleId + ':' + entityId });
btns.push({ text: '💤 Snooze 6h', callback_data: 'snooze:' + ruleId + ':' + entityId });
const reply_markup = JSON.stringify({ inline_keyboard: [btns] });
return [{ json: { chat_id: '-1003905420798', message_thread_id: 82, text, parse_mode: 'HTML', reply_markup } }];

const { rule, entityId, entityName, metrics, token } = $input.item.json;

let body = {};
if (rule.action === 'pause') body = { status: 'PAUSED', access_token: token };
else if (rule.action === 'enable') body = { status: 'ACTIVE', access_token: token };

return [{ json: { entityId, entityName, body, rule, metrics, token } }];

const { entityId, entityName, rule, metrics, token, daily_budget } = $input.item.json;
// M3: a campaign with no scalable campaign-level daily_budget (CBO / ABO budget at the
// ad-set; null/0/negative) cannot be scaled here. Make that an explicit no-op instead of
// relying on the 0*scale=0 coincidence. Also refuse a non-numeric scale_pct (NaN) rather
// than POSTing a NaN budget.
const currentCents = parseInt(daily_budget || 0) || 0;
const hasBudget = currentCents > 0;
const scalePct = Number(rule.action_params?.scale_pct ?? 20) / 100;
const validPct = Number.isFinite(scalePct);
const scaledCents = Math.round(currentCents * (1 + scalePct));
const maxCents = rule.action_params?.max_budget ? rule.action_params.max_budget * 100 : Infinity;
const newBudgetCents = validPct ? Math.min(scaledCents, maxCents) : currentCents;
const noAction = !hasBudget || !validPct || newBudgetCents === currentCents;
return [{ json: { entityId, entityName, rule, metrics, token, newBudgetCents, noAction } }];

const d = $('Evaluate Rules').item.json;
const budget = $('Budget Changed?').item.json;
const fbResult = $input.item.json;
return [{ json: {
  ...d,
  oldBudgetCents: budget.oldBudgetCents,
  newBudgetCents: budget.newBudgetCents,
  noAction: budget.noAction,
  fbResult,
  actionFailed: !!(fbResult?.error || fbResult?.message),
} }];

const d = $('Evaluate Rules').item.json;
const fbResult = $input.item.json;
return [{ json: { ...d, fbResult, actionFailed: !!(fbResult?.error || fbResult?.message) } }];

const d = $('Evaluate Rules').item.json;
const actionFailed = !!$('Restore After FB API').item.json.actionFailed;
return [{ json: { ...d, actionFailed } }];

const d = $input.item.json;
const m = d.metrics || {};
const name = d.entityName || d.entityId || '';
const ruleName = (d.rule && d.rule.name) || '';
const ruleAction = (d.rule && d.rule.action) || 'action';
const time = new Date().toLocaleTimeString('en-US', {timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit'}) + ' ET';
const isBurst = ((d.rule && d.rule.conditions) || []).some(c => c.lookback === 'last_30m');
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const safeNum = (v, dec) => (typeof v === 'number' && isFinite(v)) ? v.toFixed(dec) : '0';
let text;
try {
  if (isBurst) {
    const burst = d.burstMetrics || {};
    const pct = ((burst.burst_multiplier || 0) * 100).toFixed(0);
    text = '💥 <b>Velocity Kill: ' + esc(ruleName) + '</b>\n<code>' + esc(name) + '</code>  |  PAUSED\nLast 30 min: $' + safeNum(burst.spend_30m, 0) + ' spent (normal: $' + safeNum(burst.avg_30m, 0) + ') — ' + pct + '%\n' + time;
  } else {
    const roi = (m.roi != null && isFinite(m.roi)) ? ((m.roi * 100).toFixed(1) + '%') : 'N/A';
    const cpa = (m.cpa != null && isFinite(m.cpa)) ? ('$' + m.cpa.toFixed(0)) : 'N/A';
    const spend = (m.spend_today != null && isFinite(m.spend_today)) ? ('$' + m.spend_today.toFixed(0)) : 'N/A';
    const actionTitle = String(ruleAction).charAt(0).toUpperCase() + String(ruleAction).slice(1);
    text = '🛑 <b>' + esc(actionTitle) + ': ' + esc(ruleName) + '</b>\n<code>' + esc(name) + '</code>  |  ' + esc(String(ruleAction).toUpperCase()) + 'D\nSpend: ' + spend + '  |  ROI: ' + roi + '  |  CPA: ' + cpa + '\n' + time;
  }
} catch (e) {
  text = String(ruleAction).toUpperCase() + ': ' + String(ruleName) + ' — ' + String(name) + ' (alert build error: ' + e.message + ')';
}
const ruleId = (d.rule && d.rule.id) || '';
const entityId = d.entityId || '';
const reply_markup = JSON.stringify({ inline_keyboard: [[{ text: '✅ Re-enable', callback_data: 'reenable:' + ruleId + ':' + entityId }, { text: '💤 Snooze 6h', callback_data: 'snooze:' + ruleId + ':' + entityId }]] });
return [{ json: { chat_id: '-1003905420798', message_thread_id: 82, text, parse_mode: 'HTML', reply_markup } }];

const d = $('Evaluate Rules').item.json;
let actionFailed = false;
try { actionFailed = !!$('Restore After FB API').item.json.actionFailed; } catch(e) {}
try { if (!actionFailed) actionFailed = !!$('Restore After Scale').item.json.actionFailed; } catch(e) {}
return [{ json: {
  rule_id: d.rule.id,
  entity_type: d.rule.scope,
  entity_id: d.entityId,
  entity_name: d.entityName || d.entityId,
  action_taken: actionFailed ? d.rule.action + '_failed' : d.rule.action + 'd',
  trigger_data_json: JSON.stringify(d.metrics),
  is_dry_run: 0
} }];

const d = $('Evaluate Rules').item.json;
let entityId = d.entityId;
if (d.rule.scope === 'account') {
  const m = (d.entityName || '').match(/\(Acct (act_\d+)\)/);
  if (m) entityId = m[1];
}
return [{ json: { rule_id: d.rule.id, entity_id: entityId, type: 'cooldown', cooldown_hours: d.rule.cooldown_hours || 4 } }];

const d = $('Prepare Dry Run Log').item.json._restore;
let entityId = d.entityId;
if (d.rule && d.rule.scope === 'account') {
  const m = (d.entityName || '').match(/\(Acct (act_\d+)\)/);
  if (m) entityId = m[1];
}
return [{ json: { rule_id: d.rule.id, entity_id: entityId, type: 'cooldown', cooldown_hours: d.rule.cooldown_hours || 0.5 } }];

const items = $input.all().map(i => i.json);
return [{ json: {
  items: items.map(i => ({ rule_id: i.rule.id, entity_id: i.entityId })),
  _context: items,
} }];

const { results, _context } = $input.item.json;
const pendingMap = Object.fromEntries((results || []).map(r => [String(r.entity_id), r.pending]));
return (_context || []).map(item => {
  const key = String(item.entityId);
  // M8: fail CLOSED — if the batch-check returned no verdict for this entity, suppress.
  const pending = key in pendingMap ? !!pendingMap[key] : true;
  return { json: { ...item, pending } };
});

const items = $input.all().map(i => i.json);
return [{ json: {
  items: items.map(i => {
    let entityId = i.entityId;
    if (i.rule && i.rule.scope === 'account') {
      const m = (i.entityName || '').match(/\(Acct (act_\d+)\)/);
      if (m) entityId = m[1];
    }
    return { rule_id: i.rule.id, entity_id: entityId };
  }),
  _context: items,
} }];

const { results, _context } = $input.item.json;
const exemptMap = Object.fromEntries((results || []).map(r => [`${r.rule_id}:${String(r.entity_id)}`, r.exempt]));
return (_context || []).map(item => {
  let lookupId = item.entityId;
  if (item.rule && item.rule.scope === 'account') {
    const m = (item.entityName || '').match(/\(Acct (act_\d+)\)/);
    if (m) lookupId = m[1];
  }
  const key = `${item.rule.id}:${String(lookupId)}`;
  // M8: fail CLOSED — undeterminable exemption status is treated as exempt (suppress).
  const exempt = key in exemptMap ? !!exemptMap[key] : true;
  return { json: { ...item, exempt } };
});

const d = $input.item.json;
const m = d.metrics || {};
const name = d.entityName || d.entityId || '';
const ruleName = (d.rule && d.rule.name) || '';
const ruleId = (d.rule && d.rule.id) || '';
const entityId = d.entityId || '';
const time = new Date().toLocaleTimeString('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit' }) + ' ET';
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const roi = (m.roi != null && isFinite(m.roi)) ? (m.roi * 100).toFixed(1) + '%' : 'N/A';
const conv = (m.conversions != null && isFinite(m.conversions)) ? Math.round(m.conversions) : 'N/A';
const spend = (m.spend_today != null && isFinite(m.spend_today)) ? '$' + m.spend_today.toFixed(0) : 'N/A';
let text;
try {
  text = '\uD83C\uDFC6 <b>' + esc(ruleName) + '</b>\n<code>' + esc(name) + '</code>\nROI: ' + roi + '  Conv: ' + conv + '  Spend: ' + spend + '\n' + time;
} catch (e) {
