const { entityId, entityName, rule, metrics, token, daily_budget } = $input.item.json;
const currentCents = parseInt(daily_budget || 0) || 0;
const hasBudget = currentCents > 0;
// M4 (Option A): only act on an explicit, valid, positive decrease_pct. Missing, non-numeric
// or NaN config -> no-op (never guess a cut, never POST a NaN budget).
const rawPct = rule.action_params?.decrease_pct;
const pctNum = Number(rawPct);
const validPct = rawPct != null && Number.isFinite(pctNum) && pctNum > 0;
const decreasePct = pctNum / 100;
const minCents = rule.action_params?.min_budget ? rule.action_params.min_budget * 100 : 0;
// A decrease must never raise the budget: clamp to <= current. The min_budget floor only
// applies between the decreased value and current — it can never push the budget above current.
const decreasedCents = Math.round(currentCents * (1 - decreasePct));
const newCents = (hasBudget && validPct) ? Math.min(currentCents, Math.max(decreasedCents, minCents)) : currentCents;
const noAction = !hasBudget || !validPct || newCents === currentCents;
return [{ json: { entityId, entityName, rule, metrics, token, newBudgetCents: newCents, oldBudgetCents: currentCents, noAction } }];

function collectRules(items){ if(items.length===1){ const j=items[0].json; if(Array.isArray(j))return j; if(Array.isArray(j.data))return j.data; if(Array.isArray(j.rules))return j.rules; return [j]; } return items.map(i=>i.json); }
const rules = collectRules($input.all());
const MAX = 24;
const campMap = new Map(); const acctMap = new Map(); const tokenConflicts = [];
