  const isAcct = rule.scope==='account' && String(e.entityId).startsWith('act_');
  const target = isAcct ? acctMap : campMap; const prev = target.get(e.entityId);
  if(!prev){ target.set(e.entityId,{entityId:e.entityId,token:e.token||null}); }
  else { if(prev.token==null && e.token) prev.token=e.token; else if(e.token && prev.token && e.token!==prev.token) tokenConflicts.push({entityId:e.entityId,ruleId:rule.id}); } } }
const STATUS_FIELDS='effective_status,name,daily_budget,budget_remaining';
const INSIGHTS_FIELDS='spend,actions,action_values,purchase_roas,ctr,cpc,frequency,inline_link_clicks,outbound_clicks_ctr';
const tok=(e)=>encodeURIComponent(e.token||'');
const campEntities=[...campMap.values()].filter(e=>e.token);
const acctEntities=[...acctMap.values()].filter(e=>e.token);
const chunks=[];
for(let i=0;i<campEntities.length;i+=MAX){ const g=campEntities.slice(i,i+MAX);
  const batch=[...g.map(e=>({method:'GET',relative_url:`${e.entityId}?fields=${STATUS_FIELDS}&access_token=${tok(e)}`})),
               ...g.map(e=>({method:'GET',relative_url:`${e.entityId}/insights?fields=${INSIGHTS_FIELDS}&date_preset=today&access_token=${tok(e)}`}))];
  chunks.push({kind:'campaign',entityIds:g.map(e=>e.entityId),batch}); }
for(let i=0;i<acctEntities.length;i+=MAX){ const g=acctEntities.slice(i,i+MAX);
  const batch=g.map(e=>({method:'GET',relative_url:`${e.entityId}/insights?date_preset=today&fields=spend&access_token=${tok(e)}`}));
  chunks.push({kind:'account',entityIds:g.map(e=>e.entityId),batch}); }
const fallbackToken=(campEntities[0]||acctEntities[0]||{}).token||null;
const uniqueEntities=campEntities.length+acctEntities.length;
if(chunks.length===0) return [{json:{skip:true,reason:'No entities with tokens',tokenConflicts,uniqueEntities:0,chunkCount:0,entityIds:[]}}];
const entityIds=[...campEntities,...acctEntities].map(e=>e.entityId);
return chunks.map((c,idx)=>({json:{batch:c.batch,token:fallbackToken,kind:c.kind,entityIds:c.entityIds,chunkIndex:idx,chunkCount:chunks.length,tokenConflicts,uniqueEntities,allEntityIds:entityIds}}));

